INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 6 > Planung > Anforderungen
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Müssen Anforderungen an ein IT-System immer schriftlich dokumentiert werden, um rechtlich bindend zu sein?', 2, '[{"text": "Nein", "correct": true, "because": "Mündliche Absprachen können ebenfalls bindend sein, jedoch schwer nachweisbar"}, {"text": "Ja", "correct": false, "because": "Schriftlichkeit ist empfohlen, aber nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Können funktionale Anforderungen während der Planungsphase eines IT-Systems vollständig ignoriert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Funktionale Anforderungen definieren die Kernfunktionen des Systems"}, {"text": "Ja", "correct": false, "because": "Ignorieren führt zu einem unbrauchbaren System"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist es möglich, Anforderungen ohne Rücksprache mit dem Kunden in der Planungsphase festzulegen?', 2, '[{"text": "Ja", "correct": true, "because": "Technisch möglich, aber nicht kundenorientiert"}, {"text": "Nein", "correct": false, "because": "Kundenrücksprache ist Best Practice, aber nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind nicht-funktionale Anforderungen wie Skalierbarkeit weniger wichtig als funktionale Anforderungen?', 2, '[{"text": "Nein", "correct": true, "because": "Beide Typen sind essenziell für den Systemerfolg"}, {"text": "Ja", "correct": false, "because": "Nicht-funktionale Anforderungen sind gleichwertig"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Anforderungen in der Planungsphase unverändert bleiben, auch wenn sich die Projektziele ändern?', 2, '[{"text": "Nein", "correct": true, "because": "Anforderungen müssen an geänderte Ziele angepasst werden"}, {"text": "Ja", "correct": false, "because": "Statische Anforderungen führen zu Zielkonflikten"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Methode wird typischerweise verwendet, um Anforderungen in der Planungsphase zu erheben?', 3, '[{"text": "Interviews mit Stakeholdern", "correct": true, "because": "Direkte Kommunikation liefert präzise Informationen"}, {"text": "Zufällige Annahmen", "correct": false, "because": "Unprofessionell und unzuverlässig"}, {"text": "Hardware-Benchmarking", "correct": false, "because": "Erst nach Anforderungsdefinition relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Art von Anforderung beschreibt die erwartete Verfügbarkeit eines Systems?', 2, '[{"text": "Nicht-funktionale Anforderung", "correct": true, "because": "Verfügbarkeit ist eine Qualitätseigenschaft"}, {"text": "Funktionale Anforderung", "correct": false, "because": "Beschreibt Funktionen, nicht Eigenschaften"}, {"text": "Hardware-Anforderung", "correct": false, "because": "Zu spezifisch für Planung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel der Anforderungsanalyse in der Planung?', 2, '[{"text": "Klarstellung der Kundenwünsche", "correct": true, "because": "Basis für die Systementwicklung"}, {"text": "Festlegung der Programmiersprache", "correct": false, "because": "Spätere Umsetzungsphase"}, {"text": "Berechnung der Wartungskosten", "correct": false, "because": "Nachgelagerter Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Dokument wird oft verwendet, um Anforderungen formal festzuhalten?', 2, '[{"text": "Pflichtenheft", "correct": true, "because": "Enthält detaillierte Anforderungen"}, {"text": "Gantt-Diagramm", "correct": false, "because": "Für Zeitplanung, nicht Anforderungen"}, {"text": "Netzwerkplan", "correct": false, "because": "Für Projektstruktur, nicht Inhalte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler kann entstehen, wenn Anforderungen unklar formuliert sind?', 3, '[{"text": "Missverständnisse zwischen Kunde und Entwickler", "correct": true, "because": "Unklare Kommunikation führt zu Fehlern"}, {"text": "Schnellere Umsetzung", "correct": false, "because": "Unklarheit verzögert Prozesse"}, {"text": "Geringere Hardwarekosten", "correct": false, "because": "Irrelevant für Anforderungen"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte gehören typischerweise zu den Anforderungen in der Planung?', 4, '[{"text": "Funktionalität", "correct": true, "because": "Definiert, was das System tun soll"}, {"text": "Performance", "correct": true, "because": "Qualitätseigenschaft"}, {"text": "Sicherheit", "correct": true, "because": "Schutz vor Bedrohungen"}, {"text": "Farbe der Hardware", "correct": false, "because": "Irrelevant für Anforderungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Stakeholder sollten bei der Definition von Anforderungen einbezogen werden?', 3, '[{"text": "Kunde", "correct": true, "because": "Hauptinteressent"}, {"text": "Entwickler", "correct": true, "because": "Technische Umsetzung"}, {"text": "Projektmanager", "correct": true, "because": "Koordination"}, {"text": "Externer Lieferant", "correct": false, "because": "Nur bei Bedarf"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen eine Anforderung hochwertig?', 4, '[{"text": "Klarheit", "correct": true, "because": "Verhindert Missverständnisse"}, {"text": "Nachprüfbarkeit", "correct": true, "because": "Erfüllung überprüfbar"}, {"text": "Vollständigkeit", "correct": true, "because": "Alle Aspekte abgedeckt"}, {"text": "Vage Formulierung", "correct": false, "because": "Führt zu Unklarheiten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken entstehen durch schlecht definierte Anforderungen?', 3, '[{"text": "Kostenüberschreitung", "correct": true, "because": "Nacharbeiten erforderlich"}, {"text": "Zeitverzögerung", "correct": true, "because": "Klarstellungen nötig"}, {"text": "Kundenzufriedenheit sinkt", "correct": true, "because": "Erwartungen nicht erfüllt"}, {"text": "Schnellere Fertigstellung", "correct": false, "because": "Unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken können zur Erhebung von Anforderungen genutzt werden?', 3, '[{"text": "Workshops", "correct": true, "because": "Interaktive Diskussion"}, {"text": "Fragebögen", "correct": true, "because": "Systematische Datenerfassung"}, {"text": "Beobachtung", "correct": true, "because": "Praktische Einblicke"}, {"text": "Würfeln", "correct": false, "because": "Zufällig und unprofessionell"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Anforderungen sollten messbar formuliert werden. b) Kundenwünsche sind immer technisch umsetzbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Messbarkeit ja, Umsetzbarkeit nicht garantiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Nicht-funktionale Anforderungen betreffen oft die Benutzeroberfläche. b) Anforderungen ändern sich nie nach der Planung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht-funktional ja, Änderungen möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Pflichtenheft enthält nur funktionale Anforderungen. b) Anforderungen müssen priorisiert werden.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Pflichtenheft umfassend, Priorisierung nötig"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Anforderungen können durch Prototyping erhoben werden. b) Alle Anforderungen sind gleich wichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Prototyping ja, Priorität variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Unklare Anforderungen erhöhen das Projektrisiko. b) Die Planungsphase endet mit der Umsetzung der Anforderungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Unklarheit ja, Umsetzung später"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');
